sn_aia_tool.script:
(function execute(inputs) {
    var result = {
        found: false,
        number: "",
        use_case: "",
        problem_type: "",
        student_count: 0,
        meal_type: "",
        mess_hall: "",
        description: "",
        state: ""
    };

    var gr = new GlideRecord('x_snc_campus_foo_1_food_base_problem');

    if (!gr.get('number', inputs.food_base_problem_number)) {
        return JSON.stringify(result);
    }

    result.found = true;

    result.number = gr.getValue('number');

    result.use_case = gr.getValue('use_case');
    if (result.use_case)
        result.use_case = gr.getDisplayValue('use_case');

    result.problem_type = gr.getValue('problem_type');
    if (result.problem_type)
        result.problem_type = gr.getDisplayValue('problem_type');

    result.student_count =
        parseInt(gr.getValue('student_count'), 10) || 0;

    result.meal_type = gr.getValue('meal_type');
    if (result.meal_type)
        result.meal_type = gr.getDisplayValue('meal_type');

    result.mess_hall = gr.getValue('mess_hall');
    if (result.mess_hall)
        result.mess_hall = gr.getDisplayValue('mess_hall');

    result.description = gr.getValue('description');

    result.state = gr.getValue('state');
    if (result.state)
        result.state = gr.getDisplayValue('state');

    return JSON.stringify(result);

})(inputs);
